const findNode = (nodes: RepoTreeNode[], id: string): RepoTreeNode | undefined => {
  for (const n of nodes) {
    if (n.id === id) return n;
    const hit = n.children && findNode(n.children, id);
    if (hit) return hit;
  }
  return undefined;
};

